import { existsSync, mkdirSync, writeFileSync } from "node:fs"

const RESULTS = new URL("results/", import.meta.url)

/** Where the eval results are written. */
export const resultsDir = (): string => RESULTS.href

/** Writes one run's artifact beside the suite. */
export const record = (runId: string, artifact: unknown): string => {
  if (!existsSync(RESULTS)) mkdirSync(RESULTS, { recursive: true })
  const target = new URL(`${runId}.json`, RESULTS)
  writeFileSync(target, `${JSON.stringify(artifact, null, 2)}\n`)
  return target.href
}

export const suiteName = "mvp-evals"
